"""Offline eight-view source/critical-painted-pose reviewer. No hidden art fitting."""
from pathlib import Path
import json,base64,hashlib
P=Path(__file__).resolve().parent
s=json.loads((P/'source/source.json').read_text());g=json.loads((P/'guide-bind.json').read_text());qa=json.loads((P/'source-qa.json').read_text());views=list(s['cameras']);urls={};bindings=[]
for v in views:
 for family in ['review-source','review-skin']:
  for i in range(8):
   name=f'{family}/{v}/{i:02}.png';p=P/name;urls[name]='data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode();bindings.append(dict(path=name,sha256=hashlib.sha256(p.read_bytes()).hexdigest()))
 name=f'paint/contact-refs/{v}.png';p=P/name;urls[name]='data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode();bindings.append(dict(path=name,sha256=hashlib.sha256(p.read_bytes()).hexdigest()))
data=dict(source=s,guide=g,qa=qa,skin_qa=json.loads((P/'skin-qa.json').read_text()),hinge_qa=json.loads((P/'hinge-skin-qa.json').read_text()),views=views,bindings=bindings)
html='''<!doctype html><html lang="th"><meta charset="utf-8"><title>v43 arms / eight physical views</title><style>
body{background:#17222d;color:#edf3fc;font:16px system-ui;margin:24px}h1{font-size:25px}p{max-width:1200px;line-height:1.6}.notice{background:#4c3540;padding:14px}#views{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:20px}figure{margin:0;background:#24313f;padding:12px}canvas{width:240px;height:320px;background:#252b33;border:1px solid #5c7384}.art{max-width:240px;height:250px;object-fit:contain;display:block}button,input,select{font:inherit;margin:8px}small{display:block;max-width:260px;line-height:1.4}a{color:#96d8ff}</style>
<h1>แก้แขน / ทดสอบ motion ด้วยกล้อง 8 มุม — v43</h1>
<p class="notice">แถวภาพเคลื่อนไหวเป็นต้นแบบ 3D สำหรับตรวจ motion ไม่ใช่ภาพตัวละคร final ส่วนภาพวาดใต้แต่ละช่องเป็นท่าก้มเก็บเพียงท่าเดียว ยังไม่ใช่อนิเมชันภาพวาดครบ 8 ทิศ ภาพวาดถูกครอปจากช่องว่างของ atlas เพื่อดูรายละเอียด จึงห้ามวางกระดูกต้นแบบทับแล้วอ้างว่าพิกเซลตรงกัน</p>
<p>เครื่องมือใหม่จับข้อมือผิดในต้นแบบเดิมได้ 105.07° แม้การตรวจความหนาเดิมจะผ่านแล้ว ต้นแบบใหม่ใช้ wrist/palm ต่อจาก forearm พร้อม source world เดียวกันทุกกล้อง ตรวจความยาว/มุม/การฉายภาพ/จุดเก็บของแยกจากงานวาด</p>
<p><button id="play">เล่นต้นแบบหนึ่งครั้ง</button><input id="frame" type="range" min="0" max="7" value="0"><select id="clock"><option value="source">จังหวะ source GIF v39</option><option value="game">จังหวะ game GIF v39</option></select><select id="family"><option value="review-skin">ผิวแขน mesh ต่อเนื่องจริง</option><option value="review-source">ไกด์รูปทรงเบื้องต้น</option></select><label><input id="grid" type="checkbox">กริด20px</label><label><input id="bones" type="checkbox">กระดูกต้นแบบ</label></p><p id="status"></p><div id="views"></div>
<script>const D=__DATA__,U=__URLS__,images={},canvases={};let index=0,running=false,start=0,ready=false,clock='source';const durations=()=>clock==='source'?[190,180,190,180,190,180,190,600]:[100,100,100,100,100,100,100,600];
for(const v of D.views){const f=document.createElement('figure');f.innerHTML='<h2>'+v+'</h2><canvas width="384" height="512"></canvas><small>ต้นแบบเคลื่อนไหว: กล้องจริง / world poses เดียวกัน</small><p>ภาพวาดท่าก้มเก็บ / เฟส4 เท่านั้น</p><img class="art"><small>ภาพอ้างอิงรูปลักษณ์ท่าเดียว ยังไม่ได้ลงทะเบียนกับต้นแบบหรือพิสูจน์ภาพวาดทุกเฟรม</small>';canvases[v]=f.querySelector('canvas');f.querySelector('img').src=U['paint/contact-refs/'+v+'.png'];document.querySelector('#views').append(f)}
Promise.all(Object.entries(U).map(([k,v])=>new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>{images[k]=im;resolve()};im.onerror=reject;im.src=v}))).then(()=>{ready=true;draw()});
function point(v,k){const a=D.source.frames[index].points[k].xy[v],m=D.guide.whole_bank_matrix;return[a[0]*m[0]+m[4],a[1]*m[3]+m[5]]}
function draw(){if(!ready)return;for(const v of D.views){const x=canvases[v].getContext('2d');x.clearRect(0,0,384,512);x.drawImage(images[document.querySelector('#family').value+'/'+v+'/'+String(index).padStart(2,'0')+'.png'],0,0);if(document.querySelector('#grid').checked){x.strokeStyle='#6f94ad66';for(let j=0;j<512;j+=20){x.beginPath();x.moveTo(j+.5,0);x.lineTo(j+.5,512);x.stroke();x.beginPath();x.moveTo(0,j+.5);x.lineTo(384,j+.5);x.stroke()}}if(document.querySelector('#bones').checked){for(const [side,color] of [['left','#ff9e26'],['right','#47a4ff']]){x.strokeStyle=color;x.lineWidth=2;for(const [a,b] of [['shoulder','elbow'],['elbow','wrist'],['wrist','palm'],['palm','grip'],['hip','knee'],['knee','ankle']]){x.beginPath();x.moveTo(...point(v,side+'.'+a));x.lineTo(...point(v,side+'.'+b));x.stroke()}}}}document.querySelector('#frame').value=index;document.querySelector('#status').textContent='ต้นแบบเฟรม '+(index+1)+'/8 · '+durations()[index]+'ms · ภาพวาดด้านล่างคงอยู่ที่ท่าก้มเก็บเพื่อเทียบ anatomy เท่านั้น'}
function select(i){running=false;index=+i;draw()}function atTime(t){let sum=0,n=0;const ds=durations();while(n<7&&sum+ds[n]<=t){sum+=ds[n];n++}return n}function tick(t){if(!running)return;index=atTime(t-start);draw();if(t-start>=durations().reduce((a,b)=>a+b,0)){running=false;return}requestAnimationFrame(tick)}
document.querySelector('#play').onclick=()=>{running=true;start=performance.now();index=0;requestAnimationFrame(tick)};document.querySelector('#frame').oninput=e=>select(e.target.value);document.querySelector('#clock').onchange=e=>{clock=e.target.value;select(0)};for(const n of ['grid','bones','family'])document.querySelector('#'+n).onchange=draw;window.review={get ready(){return ready},get index(){return index},get running(){return running},get clock(){return clock},data:D,images,canvases,select,atTime};</script></html>'''
(P/'review.html').write_text(html.replace('__DATA__',json.dumps(data,separators=(',',':'))).replace('__URLS__',json.dumps(urls,separators=(',',':'))))
(P/'review-bindings.json').write_text(json.dumps(bindings,indent=2)+'\n');print('Eight-view SOURCE plus single-painted-key reviewer built')
